using UnityEngine;

/// <summary>
/// The assets M3OutdoorLife needs, in one Resources asset so a build always carries them.
///
/// The scene holds no reference to the animals, the walkers' bodies or the swaying-leaf materials
/// (the outdoor life is built at runtime by M3Surroundings, not placed in the scene), and an asset
/// nothing in a built scene references is stripped from the APK. Resources/Module3/M3OutdoorLifeSet
/// is that reference. It is generated by Module3OutdoorLifeAssets and committed, like the house
/// surface materials next to it.
/// </summary>
public class M3OutdoorLifeSet : ScriptableObject
{
    public const string ResourcePath = "Module3/M3OutdoorLifeSet";

    /// <summary>A material the shared tree prefabs use, and the same material on the Foliage Lit shader.</summary>
    [System.Serializable]
    public struct FoliageSwap
    {
        public Material from;
        public Material to;
    }

    [Tooltip("Leaf materials of the shared tree prefabs -> their copies on AEDES/Module 3/Foliage Lit, which sways.")]
    public FoliageSwap[] foliage;

    [Tooltip("Team Assets dragonflies whose materials all resolve (PF_DragonFlyYellow's do not).")]
    public GameObject[] dragonflies;

    public GameObject frog;

    [Tooltip("Bodies for the background walkers: the same villager prefabs the houses use, nothing new.")]
    public GameObject[] walkers;

    public static M3OutdoorLifeSet Load() => Resources.Load<M3OutdoorLifeSet>(ResourcePath);
}
